var i=`0317-coq-au-vin`;var t=`world-0317`;var a=`FR`;var r=`western-europe`;var s=4;var o=806;var d={en:`Coq au Vin`,ua:`Кок-о-вен`};var h={en:`A traditional France dish made with chicken thigh, bay leaf, thyme, bacon. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: куряче стегно, лавровий лист, чебрець, бекон. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var l=[{en:`Marinate the chicken in red wine with herbs overnight in the refrigerator, then drain and pat dry before browning.`,ua:`Маринуйте курятину в червоному вині з травами на ніч у холодильнику, після чого відцідіть та обсушіть перед обсмажуванням.`,t:[`marinating`],m:720,i:[[`chicken-thigh`,950,`g`],[`dry-red-wine`,450,`ml`],[`bay-leaf`,2,`leaf`],[`thyme`,3,`sprig`]]},{en:`Render bacon in a wide casserole, brown the drained chicken portions in the fat and set aside, then sauté mushrooms and pearl onions.`,ua:`Витопіть жир із бекону у широкому сотейнику, підрум’яньте обсушені порції курятини й відкладіть, після чого обсмажте гриби та дрібну цибулю.`,t:[`pan-frying`],m:14,i:[[`bacon`,160,`g`],[`extra-virgin-olive-oil`,45,`ml`],[`button-mushroom`,240,`g`],[`pearl-onion`,220,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 70 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 70 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:70,i:[[`chicken-stock`,270,`ml`],[`garlic`,4,`clove`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:2,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var c={slug:i,id:t,country:`FR`,region:r,servings:4,minutes:806,title:d,text:h,steps:l};export{a as country,c as default,t as id,o as minutes,r as region,s as servings,i as slug,l as steps,h as text,d as title};